-- =============================================================================================
-- Hand-written below this line: notification text checks; only the recipient marks it read,
-- once; content never changes. Deliveries start PENDING and write an outbox event for the worker
-- in the same transaction; their outcome is recorded only through
-- app_notification_delivery_result() (attempts counted, FAILED after the last one, SENT and
-- FAILED final; the application role cannot update deliveries directly). See docs/architecture/DATA_MODEL.md section 11 (Communications).
-- =============================================================================================

ALTER TABLE "notifications" ADD CONSTRAINT "notifications_text"
  CHECK ("kind" ~ '^[a-z][a-z0-9_.]{2,79}$'
         AND "title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND "body" = btrim("body") AND length("body") BETWEEN 1 AND 2000
         AND ("link" IS NULL OR ("link" ~ '^/[^[:space:]]*$' AND length("link") <= 400)));

CREATE FUNCTION app_notification_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW."created_at" := now();
    NEW."read_at" := NULL;
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."user_id", NEW."kind", NEW."title", NEW."body", NEW."link",
      NEW."urgent", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."user_id", OLD."kind", OLD."title", OLD."body", OLD."link",
      OLD."urgent", OLD."created_at") THEN
    RAISE EXCEPTION 'a notification never changes' USING ERRCODE = 'check_violation';
  END IF;
  IF app_current_user_id() IS DISTINCT FROM OLD."user_id" THEN
    RAISE EXCEPTION 'only the recipient marks a notification read' USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW."read_at" := coalesce(OLD."read_at", CASE WHEN NEW."read_at" IS NOT NULL THEN now() END);
  RETURN NEW;
END
$$;

CREATE TRIGGER "notifications_guard"
  BEFORE INSERT OR UPDATE ON "notifications"
  FOR EACH ROW EXECUTE FUNCTION app_notification_guard();

ALTER TABLE "notification_deliveries" ADD CONSTRAINT "notification_deliveries_state"
  CHECK ("attempts" BETWEEN 0 AND 20
         AND ("status" = 'SENT') = ("sent_at" IS NOT NULL)
         AND ("last_error" IS NULL OR length("last_error") <= 500)
         AND ("provider_reference" IS NULL OR length("provider_reference") <= 200));

CREATE FUNCTION app_notification_delivery_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'PENDING' THEN
      RAISE EXCEPTION 'deliveries start pending' USING ERRCODE = 'check_violation';
    END IF;
    NEW."attempts" := 0;
    NEW."last_error" := NULL;
    NEW."provider_reference" := NULL;
    NEW."sent_at" := NULL;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF (NEW."organisation_id", NEW."notification_id", NEW."channel", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."notification_id", OLD."channel", OLD."created_at") THEN
    RAISE EXCEPTION 'a delivery never moves' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."status" <> 'PENDING' THEN
    RAISE EXCEPTION 'delivery % is finished', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "notification_deliveries_guard"
  BEFORE INSERT OR UPDATE ON "notification_deliveries"
  FOR EACH ROW EXECUTE FUNCTION app_notification_delivery_guard();

-- Each new delivery is handed to the worker through the outbox, in the same transaction.
CREATE FUNCTION app_notification_delivery_enqueue() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  INSERT INTO "outbox_events" ("id", "organisation_id", "type", "payload", "available_at")
  VALUES (gen_random_uuid(), NEW."organisation_id", 'notification.delivery.due',
          jsonb_build_object('deliveryId', NEW."id"), now());
  RETURN NULL;
END
$$;

CREATE TRIGGER "notification_deliveries_enqueue"
  AFTER INSERT ON "notification_deliveries"
  FOR EACH ROW EXECUTE FUNCTION app_notification_delivery_enqueue();

-- The worker's record of one attempt, and the only way an outcome is written: the application
-- role has no UPDATE on deliveries, this function runs as the schema owner (row-level security
-- still applies, so only the caller's tenant). Returns the status afterwards. A delivery that is
-- no longer pending is left alone, so a duplicated job is harmless.
CREATE FUNCTION app_notification_delivery_result(p_delivery uuid, p_sent boolean, p_reference text,
                                                 p_error text, p_max_attempts int)
  RETURNS "NotificationDeliveryStatus"
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public
  AS $$
DECLARE
  d record;
  next_status "NotificationDeliveryStatus";
BEGIN
  SELECT * INTO d FROM "notification_deliveries"
   WHERE "id" = p_delivery AND "organisation_id" = app_current_organisation_id() FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such delivery' USING ERRCODE = 'no_data_found';
  END IF;
  IF d."status" <> 'PENDING' THEN
    RETURN d."status";
  END IF;
  next_status := CASE WHEN p_sent THEN 'SENT'
                      WHEN d."attempts" + 1 >= p_max_attempts THEN 'FAILED'
                      ELSE 'PENDING' END;
  UPDATE "notification_deliveries"
     SET "status" = next_status,
         "attempts" = d."attempts" + 1,
         "sent_at" = CASE WHEN p_sent THEN now() END,
         "provider_reference" = CASE WHEN p_sent THEN left(p_reference, 200) END,
         "last_error" = CASE WHEN p_sent THEN NULL ELSE left(p_error, 500) END
   WHERE "id" = p_delivery;
  RETURN next_status;
END
$$;

GRANT EXECUTE ON FUNCTION app_notification_delivery_result(uuid, boolean, text, text, int) TO veyra_app;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['notifications', 'notification_deliveries'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "notifications", "notification_deliveries" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "notifications" TO veyra_app;
-- No UPDATE: outcomes go through app_notification_delivery_result().
GRANT SELECT, INSERT ON "notification_deliveries" TO veyra_app;
